fun anchorProbe(): Boolean {
    return 1 + 2 == 3 && f() == g()
}

fun f(): Int = 1
fun g(): Int = 2

sealed class Outcome380 {
    data class Success(val payload: String) : Outcome380()
    data object Failure : Outcome380()
}

fun describe380(outcome: Outcome380): String = when (outcome) {
    is Outcome380.Success -> outcome.payload
    Outcome380.Failure -> "failed"
}
fun <T, R> List<T>.mapChecked381(transform: (T) -> R): List<R> {
    val result = mutableListOf<R>()
    for (item in this) {
        result.add(transform(item))
    }
    return result
}
class Counter382 {
    var current: Int by Delegates.observable(28) { _, _, new -> println(new) }

    suspend fun advance(): Int {
        try {
            current += 1
        } catch (failure: IllegalStateException) {
            current = 0
        } finally {
            println("advanced")
        }
        return current
    }
}
